  "canonical_name": "SSE (Cluster Quality)",
  "definition": {
    "status": "grounded",
    "grounding_mode": "contextual_synthesis",
    "text": "Sum of the squared error (SSE), also known as scatter, is a measure of clustering quality calculated by summing the squared Euclidean distances from each data point to its closest centroid.",
    "supporting_evidence_ids": [
      "E2"
    ],
    "supporting_lanes": [
      "context_lane"
    ],
    "abstention_reason": ""
  },
  "scope": {
    "status": "grounded",
    "grounding_mode": "contextual_synthesis",
    "text": "SSE is used to compare different K-means clustering results, where a smaller squared error indicates that centroids better represent the points in their cluster; lower SSE is associated with better clustering results.",
    "supporting_evidence_ids": [
      "E2",
      "E3"
    ],
    "supporting_lanes": [
